const experimentsBase = 'https://adamwebsite.com/experiments/';
const codevemberBase = 'https://adamwebsite.com/codevember/';
const codevemberSource = 'https://github.com/acher249/codevember-2026/tree/main/';

export const groups = [
  { id: 'codevember', label: 'Codevember' },
  { id: 'core', label: '核心实验' },
  { id: 'r3f', label: 'React Three Fiber' },
  { id: 'three', label: '原生 Three.js' },
  { id: 'learning', label: '交互科普' },
];

function codevember(day, exhibit) {
  const path = `${day}-${exhibit.id}`;
  return {
    group: 'codevember',
    url: `${codevemberBase}${path}/`,
    source: `${codevemberSource}${path}`,
    poster: `${codevemberBase}${path}.jpg`,
    ...exhibit,
  };
}

function experiment(group, exhibit, path = exhibit.id) {
  return { group, url: `${experimentsBase}${path}/`, ...exhibit };
}

